// The target directory's `index.ts` barrel belongs to the consumer once it exists. These helpers
// only ever append missing `export * from './<component>';` lines: nothing already in the file
// (comments, imports, curated exports, formatting) is rewritten or reordered.

const INITIAL_BARREL = `// UI Components
// Generated by volt CLI

export {};
`;

// The placeholder `volt init` writes so an empty barrel is still a module. It is dropped only when
// it stands alone on its own line, and only once real exports replace it.
const PLACEHOLDER_LINE = /^export \{\};[ \t]*(?:\r?\n|$)/m;

/** Removes comments so a commented-out export is not mistaken for a live one. */
function stripComments(source) {
  return source.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:'"`])\/\/.*$/gm, '$1');
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Whether the barrel already re-exports a component folder, in any form the consumer may have
 * written it: `export * from './button'`, `export { UiButton } from "./button/index"`, with or
 * without an extension. A curated `export { … }` counts — the consumer chose what to expose.
 */
function hasExportFor(content, componentName) {
  const specifier = `\\./${escapeRegExp(componentName)}(?:/index)?(?:\\.(?:js|ts))?`;
  const pattern = new RegExp(`\\bexport\\b[^;]*?\\bfrom\\s*(['"])${specifier}\\1`);
  return pattern.test(stripComments(content));
}

/**
 * Returns the barrel content after adding the components it does not export yet, plus the list
 * of components added. `content` is `null` when the barrel does not exist.
 */
function addBarrelExports(content, componentNames) {
  const existing = content ?? '';
  const added = [];
  for (const name of componentNames) {
    if (!added.includes(name) && !hasExportFor(existing, name)) added.push(name);
  }
  if (added.length === 0) return { content: existing, added };

  const eol = existing.includes('\r\n') ? '\r\n' : '\n';
  let base = existing;
  if (PLACEHOLDER_LINE.test(base)) base = base.replace(PLACEHOLDER_LINE, '');
  if (base.length > 0 && !base.endsWith('\n')) base += eol;
  const lines = added.map(name => `export * from './${name}';`).join(eol);
  return { content: `${base}${lines}${eol}`, added };
}

module.exports = { INITIAL_BARREL, addBarrelExports, hasExportFor };
